contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 val) public payable {
        bool reverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(!reverted && c.MinSum() == val);
    }

    receive() external payable {}
}

